# Code generated by Claude
"""Policy command source: runs a policy function each tick and turns its output into control loop commands.

The policy is a callable policy(obs, t) that returns an array of actuator targets indexed by actuator id (the
interface of models/policies/*.py). The source uses only the actuators it is given (the actuators of the "auto"
control groups), as in the old experiments/combined_controller.py. The array is turned into commands:
  arm joint actuators  -> an arms command (arm_targets per side; joints the policy does not cover keep the applied value)
  finger actuators     -> gripper (both fingers of a side take the first finger's value)
  the pedestal         -> a pedestal command
  the wheel motors     -> ignored (the base is velocity-driven, as before)

    source = make_policy_source(model, policy, ids)
    source["claims"]   the actuator ids the policy owns (they are not "unclaimed" hold actuators)
    source["routes"]   the router entries to hand to the loop: {"arms.right": "policy", ...}
"""

import re

import numpy as np

from src import robot_specs


def make_policy_source(model, policy, ids):
    """Create a command source around a policy function.

    Sorts the given actuators into arm joints, fingers and the pedestal by
    their names ("<side>_joint<1-7>_ctrl", "<side>_finger<1|2>_ctrl" and the
    pedestal actuator named in robot_specs.PEDESTAL_SPECS); any other
    actuator (for example the wheels) is ignored.

    Args:
        model (mujoco.MjModel): The robot model, used to look up actuator
            names.
        policy (Callable[[dict, float], numpy.ndarray]): Called as
            policy(obs, t) with the observation and the simulated time in
            seconds. Returns targets indexed by actuator id: joint angles in
            radians for arm joints, finger travel in metres for fingers, the
            pedestal height in metres.
        ids (Iterable[int]): Actuator ids that the policy owns.

    Returns:
        dict: The source, with these keys:
            "name" (str): "policy".
            "step" (Callable[[dict], list[dict]]): Takes the observation and
                returns the commands (see step() inside this function).
            "claims" (list[int]): The actuator ids, sorted. The loop does not
                hold these at the rest pose.
            "routes" (dict[str, str]): Router entries to give the loop, each
                with the value "policy": "arms.left" and "arms.right" for each
                side that has an arm joint among `ids`, "gripper.left" and
                "gripper.right" for each side that has a finger, and
                "pedestal" if the pedestal actuator is among `ids`.
    """
    ped_name = robot_specs.PEDESTAL_SPECS["actuator_name"]
    arm_ids = {"left": {}, "right": {}}      # side -> {joint index 0-6: actuator id}
    finger_ids = {"left": [], "right": []}
    ped_id = None
    for aid in ids:
        name = model.actuator(aid).name
        m = re.fullmatch(r"(left|right)_joint([1-7])_ctrl", name)
        f = re.fullmatch(r"(left|right)_finger([12])_ctrl", name)
        if m:
            arm_ids[m.group(1)][int(m.group(2)) - 1] = aid
        elif f:
            finger_ids[f.group(1)].append(aid)
        elif name == ped_name:
            ped_id = aid
    routes = {}
    for side in ("left", "right"):
        if arm_ids[side]:
            routes[f"arms.{side}"] = "policy"
        if finger_ids[side]:
            routes[f"gripper.{side}"] = "policy"
    if ped_id is not None:
        routes["pedestal"] = "policy"

    def step(obs):
        """Run the policy once and convert its targets into commands.

        Args:
            obs (dict): Observation from the control loop. Uses obs["time"]
                (simulated seconds, passed to the policy) and
                obs["applied"]["arm_targets"] (the arm joint targets in
                radians by side; joints the policy does not own keep these
                values). The whole of `obs` is passed to the policy.

        Returns:
            list[dict]: Up to two commands. {"mode": "arms", "arm_targets":
            {side: [7 radians]}, "gripper": {side: finger travel in metres}}
            (either entry is left out if the policy owns no such actuator) and
            {"mode": "pedestal", "height": metres}. Empty if the policy owns no
            usable actuator.
        """
        pt = policy(obs, obs["time"])
        cmds = []
        arm_targets, grip = {}, {}
        for side in ("left", "right"):
            if arm_ids[side]:
                q = list(obs["applied"]["arm_targets"][side])
                for j, aid in arm_ids[side].items():
                    q[j] = float(pt[aid])
                arm_targets[side] = q
            if finger_ids[side]:
                grip[side] = float(pt[finger_ids[side][0]])
        if arm_targets or grip:
            cmd = {"mode": "arms"}
            if arm_targets:
                cmd["arm_targets"] = arm_targets
            if grip:
                cmd["gripper"] = grip
            cmds.append(cmd)
        if ped_id is not None:
            cmds.append({"mode": "pedestal", "height": float(pt[ped_id])})
        return cmds

    return {"name": "policy", "step": step, "claims": sorted(ids), "routes": routes}
